import raw from "./teardowns.json";

export type TeardownPhoto = {
  file: string;
  date: string; // ISO 8601, from EXIF
  width: number;
  height: number;
  caption: string;
};

export type Teardown = {
  slug: string;
  title: string;
  description: string;
  photos: TeardownPhoto[]; // sorted oldest first
};

// Generated by scripts/import-teardown-photos.py; captions and
// descriptions are hand-edited in teardowns.json and survive re-import.
export const teardowns: Teardown[] = raw;

export function teardownImage(
  slug: string,
  tier: "full" | "display" | "thumb",
  file: string
) {
  return `images/teardowns/${slug}/${tier}/${file}`;
}

export function latestDate(t: Teardown): string {
  return t.photos.length ? t.photos[t.photos.length - 1].date : "";
}
